// Des: Tests for sync upgrades: compact bodies, ledger, verified uploads
// Flo: temp db + mock cloud + real raw files > sync > assert statements, ledger rows, pack rows, flags
// I/O: mock cloud > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const sync = @import("sy-clou-sync.zig"); const cmok = @import("sy-clou-mock.zig"); const outb = @import("sy-clou-outb.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const file = @import("st-stor-file.zig"); const hash = @import("ut-hash-dedu.zig"); const pack = @import("ru-purg-pack.zig");
const allo = std.testing.allocator;
const NOWZ: i64 = 1795528470301;
const DAYZ: i64 = 86400000;
const Rigg = struct { tmpz: std.testing.TmpDir, cldz: cmok.Mock, cld2: cmok.Mock, dirz: []u8, rawd: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, synz: sync.Sync,
pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.rawd = try std.fs.path.join(allo, &.{ self.dirz, "raw" }); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.cldz = cmok.Mock.init(allo); self.cld2 = cmok.Mock.init(allo); self.synz = .{ .iozz = std.testing.io, .dbzz = &self.dbzz, .dirz = self.dirz, .conf = .{}, .store = self.cldz.store(), .sql2 = self.cldz.sql2() }; }
pub fn down(self: *Rigg) void { self.cldz.deinit(); self.cld2.deinit(); self.aren.deinit(); self.dbzz.close(); allo.free(self.rawd); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn fileAddz(self: *Rigg, body: []const u8) ![]const u8 { const sav2 = try file.fileSave(allo, std.testing.io, self.rawd, body); const hexz = try self.aren.allocator().dupe(u8, &sav2.hexz); try outb.outbAddz(&self.dbzz, "file", hexz, 0, false); return hexz; }
pub fn recoAddz(self: *Rigg, urlz: []const u8, code: i64, fetc: i64, body: []const u8) !void { try inde.pageSetz(&self.dbzz, urlz, .{ .hexz = "h", .etag = "", .lmod = "", .code = code, .tier = 1, .vend = "", .fetc = fetc, .next = 2 }); try inde.recoSetz(&self.dbzz, urlz, .{ .hexz = "h", .kind = "text", .body = body }, fetc); try outb.outbAddz(&self.dbzz, "rec", urlz, 0, false); }
pub fn scal(self: *Rigg, sqlz: [:0]const u8) !i64 { var stmt = try self.dbzz.prep(sqlz); defer stmt.fini(); if (!try stmt.step()) return -1; return stmt.colzIntz(0); } };
test "record bodies are cut to clou_body_maxz and the ledger holds url + body + overhead" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); rig3.synz.conf.clou_body_maxz = 1024; const bigz = try allo.alloc(u8, 5000); defer allo.free(bigz); @memset(bigz, 'x'); try rig3.recoAddz("http://a/big", 200, NOWZ, bigz); const rslt = try sync.syncRunz(&rig3.synz, rig3.aren.allocator(), NOWZ + 1000); try std.testing.expectEqual(@as(u32, 1), rslt.recs); var seen = false; for (rig3.cldz.stm2.items) |item| { if (std.mem.indexOf(u8, item, "INTO cl_reco") != null) { seen = true; try std.testing.expect(item.len < 1500); try std.testing.expect(item.len > 1024); } } try std.testing.expect(seen); try std.testing.expectEqual(@as(i64, "http://a/big".len + 1024 + 200), try rig3.scal("SELECT byts FROM dbcl;")); }
test "a gone URL older than the limit is not uploaded, a fresh gone one is, the outbox drains" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.recoAddz("http://a/goneold", 404, NOWZ - 100 * DAYZ, "x"); try rig3.recoAddz("http://a/gonenew", 410, NOWZ - DAYZ, "x"); try rig3.recoAddz("http://a/live", 200, NOWZ - 100 * DAYZ, "x"); const rslt = try sync.syncRunz(&rig3.synz, rig3.aren.allocator(), NOWZ + 1000); try std.testing.expectEqual(@as(u32, 2), rslt.recs); try std.testing.expectEqual(@as(usize, 2), rig3.cldz.sawzStmt("INTO cl_page")); try std.testing.expectEqual(@as(i64, 0), try outb.outbCont(&rig3.dbzz, 0)); try std.testing.expectEqual(@as(i64, 2), try rig3.scal("SELECT count(*) FROM dbcl;")); }
test "a verified upload stores the time and the vendor name; a wrong listed size stays unverified" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); rig3.synz.vnam = "mock1"; const h1zz = try rig3.fileAddz("first body for the verified pack"); const rsl1 = try sync.syncRunz(&rig3.synz, rig3.aren.allocator(), NOWZ); try std.testing.expect(rsl1.veri); var sel1 = try rig3.dbzz.prep("SELECT vfyz,vend FROM pack WHERE hexz=?1;"); defer sel1.fini(); try sel1.bindText(1, h1zz); try std.testing.expect(try sel1.step()); try std.testing.expectEqual(NOWZ, sel1.colzIntz(0)); try std.testing.expectEqualStrings("mock1", sel1.colzText(1)); rig3.cldz.badl = true; const h2zz = try rig3.fileAddz("second body for the unverified pack"); const rsl2 = try sync.syncRunz(&rig3.synz, rig3.aren.allocator(), NOWZ + 5000); try std.testing.expect(!rsl2.veri); var sel2 = try rig3.dbzz.prep("SELECT vfyz FROM pack WHERE hexz=?1;"); defer sel2.fini(); try sel2.bindText(1, h2zz); try std.testing.expect(try sel2.step()); try std.testing.expectEqual(@as(i64, 0), sel2.colzIntz(0)); }
test "a failed run says which layer failed: SQL only, store only" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.fileAddz("body one"); var rsl1: sync.Sres = .{}; rig3.cldz.sqlo = true; try std.testing.expectError(error.CloudSql, sync.syncRunx(&rig3.synz, rig3.aren.allocator(), NOWZ, &rsl1)); try std.testing.expectEqual(sync.LAYZ_SQLZ, rsl1.lays); rig3.cldz.sqlo = false; rig3.cldz.stoo = true; var rsl2: sync.Sres = .{}; try std.testing.expectError(error.CloudHttp, sync.syncRunx(&rig3.synz, rig3.aren.allocator(), NOWZ + 3600000 * 7, &rsl2)); try std.testing.expectEqual(sync.LAYZ_STOR, rsl2.lays); rig3.cldz.stoo = false; var rsl3: sync.Sres = .{}; try sync.syncRunx(&rig3.synz, rig3.aren.allocator(), NOWZ + 3600000 * 20, &rsl3); try std.testing.expectEqual(@as(u8, 0), rsl3.lays); try std.testing.expectEqual(@as(u32, 1), rsl3.fil2); }
test "reads follow the vendor name; a keep pack falls back to the copy store" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const pool = [_]sync.Vsto{ .{ .name = "v1", .store = rig3.cldz.store() }, .{ .name = "v2", .store = rig3.cld2.store() } }; rig3.synz.store = rig3.cld2.store(); rig3.synz.pool = &pool; const aren = rig3.aren.allocator(); const body = "page body that lives on vendor one"; const part: pack.Part = .{ .hexz = try aren.dupe(u8, &hash.hashHexz(body)), .gzzz = try file.gzipPack(aren, body) }; const byts = try pack.packBuil(aren, &.{part}); const ents = try pack.packPars(aren, byts); const sto1 = rig3.cldz.store(); try sto1.put(sto1.ctx2, aren, std.testing.io, "runs/20261124.pack", byts); try rig3.dbzz.exec("INSERT INTO pack(hexz,packk,offs,lenz,vend) VALUES('x','runs/20261124.pack',0,0,'v1');"); var insz = try rig3.dbzz.prep("UPDATE pack SET hexz=?1,offs=?2,lenz=?3;"); defer insz.fini(); try insz.bindText(1, part.hexz); try insz.bindIntz(2, @intCast(ents[0].offs)); try insz.bindIntz(3, @intCast(ents[0].lenz)); _ = try insz.step(); const got1 = try sync.res3(&rig3.synz, aren, part.hexz[0..64].*); try std.testing.expectEqualStrings(body, got1); try rig3.dbzz.exec("UPDATE pack SET packk='keep/20261124.pack',vend='v1';"); const sto2 = rig3.cld2.store(); try sto2.put(sto2.ctx2, aren, std.testing.io, "keep/20261124.pack", byts); rig3.synz.copy = rig3.cld2.store(); const got2 = try sync.res3(&rig3.synz, aren, part.hexz[0..64].*); try std.testing.expectEqualStrings(body, got2); rig3.synz.copy = null; try std.testing.expectError(error.CloudHttp, sync.res3(&rig3.synz, aren, part.hexz[0..64].*)); }
test "outbSoon makes backed-off rows due again, finished rows stay finished" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const h1zz = try rig3.fileAddz("soon body one"); _ = try rig3.fileAddz("soon body two"); try outb.outbFail(&rig3.dbzz, "file", h1zz, "boom", NOWZ); try std.testing.expectEqual(@as(usize, 1), (try outb.outbDuez(&rig3.dbzz, rig3.aren.allocator(), "file", NOWZ, 10)).len); try outb.outbSoon(&rig3.dbzz, NOWZ); try std.testing.expectEqual(@as(usize, 2), (try outb.outbDuez(&rig3.dbzz, rig3.aren.allocator(), "file", NOWZ, 10)).len); try outb.outbDone(&rig3.dbzz, "file", h1zz); try outb.outbSoon(&rig3.dbzz, NOWZ + 5); try std.testing.expectEqual(@as(usize, 1), (try outb.outbDuez(&rig3.dbzz, rig3.aren.allocator(), "file", NOWZ + 5, 10)).len); }
test "upgrade backfill: old records get ledger rows once, old packs get the first store name once" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.dbzz.exec("INSERT INTO pack(hexz,packk,offs,lenz) VALUES('h1','runs/old',0,1); INSERT INTO pack(hexz,packk,offs,lenz,vend) VALUES('h2','runs/new',0,1,'turs');"); try inde.pageSetz(&rig3.dbzz, "http://old/a", .{ .hexz = "h", .etag = "", .lmod = "", .code = 200, .tier = 1, .vend = "", .fetc = 1, .next = 2 }); try inde.recoSetz(&rig3.dbzz, "http://old/a", .{ .hexz = "h", .kind = "text", .body = "0123456789" }, 1); try std.testing.expectEqual(@as(u32, 1), try sync.ledgBack(&rig3.synz, rig3.aren.allocator())); try std.testing.expectEqual(@as(i64, "http://old/a".len + 10 + 200), try rig3.scal("SELECT byts FROM dbcl;")); try rig3.dbzz.exec("DELETE FROM dbcl;"); try std.testing.expectEqual(@as(u32, 0), try sync.ledgBack(&rig3.synz, rig3.aren.allocator())); try std.testing.expectEqual(@as(i64, 0), try rig3.scal("SELECT count(*) FROM dbcl;")); try sync.vendBack(&rig3.synz, "b2zz"); try std.testing.expectEqual(@as(i64, 1), try rig3.scal("SELECT count(*) FROM pack WHERE vend='b2zz';")); try std.testing.expectEqual(@as(i64, 1), try rig3.scal("SELECT count(*) FROM pack WHERE vend='turs';")); }
